 INSERT INTO academico_catalogo_disciplinas(nome,nome_chave,legado) SELECT d.nome,CONCAT('legado:',d.id_disciplina),TRUE FROM academico_disciplinas d WHERE NOT EXISTS(SELECT 1 FROM academico_oferta_catalogo x WHERE x.id_disciplina=d.id_disciplina) ON DUPLICATE KEY UPDATE nome=academico_catalogo_disciplinas.nome;
 INSERT INTO academico_oferta_catalogo(id_disciplina,id_catalogo) SELECT d.id_disciplina,c.id_catalogo FROM academico_disciplinas d JOIN academico_catalogo_disciplinas c ON c.nome_chave=CONCAT('legado:',d.id_disciplina) WHERE TRUE ON DUPLICATE KEY UPDATE id_catalogo=academico_oferta_catalogo.id_catalogo;
 INSERT INTO academico_vinculos_turma(id_turma,id_aluno,id_curso) SELECT DISTINCT t.id_turma,m.id_aluno,t.id_curso FROM academico_matriculas m JOIN academico_disciplinas d ON d.id_disciplina=m.id_disciplina JOIN academico_turmas t ON t.id_turma=d.id_turma JOIN usuarios u ON u.id_usuario=m.id_aluno WHERE m.ativa=1 AND u.tipo_usuario='discente' AND u.situacao='ativo' AND d.arquivada_em IS NULL AND t.arquivada_em IS NULL AND (SELECT COUNT(DISTINCT t2.id_turma) FROM academico_matriculas m2 JOIN academico_disciplinas d2 ON d2.id_disciplina=m2.id_disciplina JOIN academico_turmas t2 ON t2.id_turma=d2.id_turma WHERE m2.id_aluno=m.id_aluno AND m2.ativa=1 AND d2.arquivada_em IS NULL AND t2.arquivada_em IS NULL AND t2.id_curso=t.id_curso)=1 ON DUPLICATE KEY UPDATE id_aluno=academico_vinculos_turma.id_aluno;
 INSERT INTO academico_gestao_historico(tipo,id_alvo,acao,nome_autor,motivo) SELECT 'vinculo',m.id_aluno,'revisao_legado','Migracao1.1.31','Matriculas legadas em mais de uma turma do mesmo curso. Nenhuma transferencia automatica.' FROM academico_matriculas m JOIN academico_disciplinas d ON d.id_disciplina=m.id_disciplina JOIN academico_turmas t ON t.id_turma=d.id_turma WHERE m.ativa=1 AND d.arquivada_em IS NULL AND t.arquivada_em IS NULL AND NOT EXISTS(SELECT 1 FROM academico_gestao_historico h WHERE h.tipo='vinculo' AND h.id_alvo=m.id_aluno AND h.acao='revisao_legado') GROUP BY m.id_aluno,t.id_curso HAVING COUNT(DISTINCT t.id_turma)>1;
 INSERT IGNORE INTO arcadia_schema_migrations(versao,checksum) VALUES('1.1.31','65b9e91ba1ee9ae3025c3078ee3a8e61e278640c482d384a0f35d154bd0ad326');
END$$
